struct SelectedAuth(CodexAuth);

impl ExternalAuth for SelectedAuth {
    fn resolve(&self) -> ExternalAuthFuture<'_, CodexAuth> {
        Box::pin(async { Ok(self.0.clone()) })
    }

    fn refresh(&self, _context: ExternalAuthRefreshContext) -> ExternalAuthFuture<'_, CodexAuth> {
        self.resolve()
    }
}

#[derive(Default)]
struct StallingAuth {
    stall: AtomicBool,
    released: CancellationToken,
}

impl ExternalAuth for StallingAuth {
    fn resolve(&self) -> ExternalAuthFuture<'_, CodexAuth> {
        Box::pin(async {
            if self.stall.load(Ordering::SeqCst) {
                self.released.cancelled().await;
            }
            Ok(header_auth("Bearer rotated"))
        })
    }

    fn refresh(&self, _context: ExternalAuthRefreshContext) -> ExternalAuthFuture<'_, CodexAuth> {
        self.resolve()
    }
}

fn header_auth(token: &'static str) -> CodexAuth {
    // Without stable account metadata, credential rotation must invalidate the catalog.
    CodexAuth::Headers(AuthHeaders::new(HeaderMap::from_iter([(
        http::header::AUTHORIZATION,
        HeaderValue::from_static(token),
    )])))
}

#[derive(Clone, Copy)]
enum Input {
    User,
    Mail,
}

#[derive(Clone, Copy)]
enum RefreshOutcome {
    Success,
    Failure,
    AuthTimeout,
}

#[test_case(Input::User, RefreshOutcome::Success; "user refresh")]
#[test_case(Input::User, RefreshOutcome::Failure; "user fallback")]
#[test_case(Input::Mail, RefreshOutcome::Success; "mail refresh")]
#[test_case(Input::Mail, RefreshOutcome::Failure; "mail fallback")]
#[test_case(Input::User, RefreshOutcome::AuthTimeout; "auth timeout")]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn auth_rotation_refreshes_before_turn_with_best_effort(
    input: Input,
    outcome: RefreshOutcome,
) -> Result<()> {
    let server = MockServer::start().await;
    let catalog = bundled_models_response()?;
    let mut model = catalog
        .models
        .iter()
        .find(|model| model.slug == "gpt-5.5")
        .cloned()
        .expect("bundled model");
    let fallback_context_window = model.usable_context_window();
    responses::mount_models_once(&server, catalog).await;
    let test = test_codex()
        .with_auth(header_auth("Bearer rotated"))
        .with_model(&model.slug)
        .with_config(|config| config.model_provider.request_max_retries = Some(0))
        .build_with_auto_env(&server)
        .await?;
    model.visibility = ModelVisibility::List;
    model.context_window = Some(481_000);
    model.max_context_window = Some(481_000);
    model.effective_context_window_percent = 100;
    model.use_responses_lite = true;
    model.tool_mode = Some(ToolMode::CodeModeOnly);
    let succeeds = matches!(outcome, RefreshOutcome::Success);
    let stalls_auth = matches!(outcome, RefreshOutcome::AuthTimeout);
    let expected_context_window = if succeeds {
        model.usable_context_window()
    } else {
        fallback_context_window
    };
    let template = if succeeds {
        ResponseTemplate::new(/*s*/ 200).set_body_json(ModelsResponse {
            models: vec![model],
        })
    } else {
        ResponseTemplate::new(/*s*/ 503).set_body_string("unavailable")
    };
    Mock::given(method("GET"))
        .and(path("/v1/models"))
        .and(header("authorization", "Bearer rotated"))
        .respond_with(template)
        .expect(/*r*/ u64::from(!stalls_auth))
        .mount(&server)
        .await;
    let stalled_auth = Arc::new(StallingAuth::default());
    // The shared picker can replace the catalog between turns. Switching back
    // must refresh even when this was the last identity used to start a turn.
    test.thread_manager
        .auth_manager()
        .set_external_auth(Arc::new(SelectedAuth(header_auth("Bearer other"))))
        .await?;
    responses::mount_models_once(&server, bundled_models_response()?).await;
    test.thread_manager
        .get_models_manager()
        .raw_model_catalog(
            RefreshStrategy::Online,
            codex_core::test_support::default_http_client_factory(),
        )
        .await;
    let auth: Arc<dyn ExternalAuth> = if stalls_auth {
        stalled_auth.clone()
    } else {
        Arc::new(SelectedAuth(header_auth("Bearer rotated")))
    };
    test.thread_manager
        .auth_manager()
        .set_external_auth(auth)
        .await?;
    stalled_auth.stall.store(stalls_auth, Ordering::SeqCst);
    let response = responses::mount_sse_once(&server, responses::sse_completed("done")).await;
    match input {
        Input::User => {
            tokio::time::timeout(
                Duration::from_secs(/*secs*/ 7),
                test.codex
                    .start_or_steer_turn(TurnInputRequest::user_input(vec![UserInput::Text {
                        text: "hello".into(),
                        text_elements: Vec::new(),
                    }])),
            )
            .await??;
        }
        Input::Mail => {
            test.codex
                .submit(Op::InterAgentCommunication {
                    communication: InterAgentCommunication::new(
                        AgentPath::root().join("worker").expect("valid path"),
                        AgentPath::root(),
                        Vec::new(),
                        "hello".into(),
                        /*trigger_turn*/ true,
                    ),
                    start_options: Default::default(),
                })
                .await?;
        }
    }
    let started = wait_for_event(&test.codex, |event| {
        matches!(event, EventMsg::TurnStarted(_))
    })
    .await;
    let EventMsg::TurnStarted(started) = started else {
        unreachable!()
    };
    assert_eq!(started.model_context_window, expected_context_window);
    if stalls_auth {
        stalled_auth.stall.store(/*val*/ false, Ordering::SeqCst);
        stalled_auth.released.cancel();
    }
    wait_for_event(&test.codex, |event| {
        matches!(event, EventMsg::TurnComplete(_))
    })
    .await;
    let request = response.single_request();
    assert!(request.body_contains_text("hello"));
    assert_eq!(
        request.header("authorization").as_deref(),
        Some("Bearer rotated")
    );
    let body = request.body_json();
    let uses_responses_lite = body["input"]
        .as_array()
        .expect("request input")
        .iter()
        .any(|item| item["type"] == "additional_tools");
    assert_eq!(uses_responses_lite, succeeds);
    test.codex.submit(Op::Shutdown).await?;
    test.codex.wait_until_terminated().await;
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn auth_and_provider_switches_do_not_reuse_chatgpt_catalog() -> Result<()> {
    let server = wiremock::MockServer::start().await;
    let home = Arc::new(TempDir::new()?);
    let mut model = bundled_models_response()?
        .models
        .into_iter()
        .find(|model| model.slug == "gpt-5.5")
        .unwrap();
    model.visibility = ModelVisibility::List;
    model.default_service_tier = Some("priority".into());
    let models_mock = responses::mount_models_once(
        &server,
        ModelsResponse {
            models: vec![model.clone()],
        },
    )
    .await;
    let chatgpt = test_codex()
        .with_home(home.clone())
        .with_auth(CodexAuth::create_dummy_chatgpt_auth_for_testing())
        .with_model("gpt-5.5")
        .build_with_auto_env(&server)
        .await?;
    assert!(home.path().join("models_cache.json").exists());
    assert_eq!(
        chatgpt
            .thread_manager
            .get_models_manager()
            .get_remote_models()
            .await,
        vec![model.clone()]
    );
    login_with_api_key(
        home.path(),
        "api-key",
        AuthCredentialsStoreMode::File,
        AuthKeyringBackendKind::default(),
    )?;
    assert!(chatgpt.thread_manager.auth_manager().reload().await);
    let manager = chatgpt.thread_manager.get_models_manager();
    let bundled = bundled_models_response()?.models;
    assert_eq!(manager.get_remote_models().await, bundled);
    assert_eq!(
        manager
            .raw_model_catalog(
                RefreshStrategy::Offline,
                codex_core::test_support::default_http_client_factory()
            )
            .await
            .models,
        bundled
    );
    assert_eq!(models_mock.requests().len(), 1);
    drop(chatgpt);
    server.reset().await;

    let mut api_model = model.clone();
    api_model.default_service_tier = None;
    let api_models_mock = responses::mount_models_once(
        &server,
        ModelsResponse {
            models: vec![api_model],
        },
    )
    .await;
    let api = test_codex()
        .with_home(home.clone())
        .with_auth(CodexAuth::from_api_key("api-key"))
        .with_config(|config| {
            config.model_provider.model_catalog_url = config
                .model_provider
                .base_url
                .as_ref()
                .map(|base_url| format!("{base_url}/models").into());
            config
                .features
                .enable(codex_features::Feature::ApiKeyModelDiscovery)
                .expect("enable API-key model discovery");
        })
        .with_model("gpt-5.5")
        .build_with_auto_env(&server)
        .await?;
    let ordinary = responses::mount_sse_once(
        &server,
        sse(vec![
            ev_response_created("ordinary"),
            ev_completed("ordinary"),
        ]),
    )
    .await;
    api.submit_turn("hello").await?;
    assert_eq!(
        ordinary.single_request().body_json().get("service_tier"),
        None
    );

    let explicit = responses::mount_sse_once(
        &server,
        sse(vec![
            ev_response_created("explicit"),
            ev_completed("explicit"),
        ]),
    )
    .await;
    api.submit_turn_with_service_tier("hello again", Some("priority"))
        .await?;
    assert_eq!(
        explicit.single_request().body_json()["service_tier"],
        "priority"
    );
    assert_eq!(api_models_mock.requests().len(), 1);
    drop(api);

    let other_server = wiremock::MockServer::start().await;
    model.default_service_tier = None;
    model.display_name = "Second provider model".into();
    let other_models = responses::mount_models_once(
        &other_server,
        ModelsResponse {
            models: vec![model.clone()],
        },
    )
    .await;
    let other = test_codex()
        .with_home(home)
        .with_auth(CodexAuth::create_dummy_chatgpt_auth_for_testing())
        .with_model("gpt-5.5")
        .with_config(|config| {
            config.model_provider_id = "second".into();
            config.model_provider.name = "Second".into();
        })
        .build_with_auto_env(&other_server)
        .await?;
    assert_eq!(
        other
            .thread_manager
            .get_models_manager()
            .get_remote_models()
            .await,
        vec![model]
    );
    assert_eq!(other_models.requests().len(), 1);
    Ok(())
}

//! Serialized read-refresh-write transactions for MCP OAuth credentials.

use std::time::Duration;
use std::time::SystemTime;
use std::time::UNIX_EPOCH;

use anyhow::Context;
use anyhow::Error;
use anyhow::Result;
use codex_config::McpServerOAuthConfig;
use codex_keyring_store::DefaultKeyringStore;
use codex_keyring_store::KeyringStore;
use oauth2::TokenResponse;
use rmcp::transport::auth::AuthError;
use rmcp::transport::auth::AuthorizationManager;
use rmcp::transport::auth::CredentialStore as _;
use rmcp::transport::auth::InMemoryCredentialStore;
use rmcp::transport::auth::OAuthTokenResponse;
use rmcp::transport::auth::StoredCredentials;
use tokio::time::timeout;
use tracing::debug;
use tracing::warn;

use crate::oauth_client_credentials::OAuthClientCredentials;

use super::OAuthPersistor;
use super::OAuthPersistorInner;
use super::StoredOAuthTokens;
use super::WrappedOAuthTokenResponse;
use super::compute_expires_at_millis;
use super::expires_in_from_timestamp;
use super::refresh_lock::RefreshCredentialLock;
use super::token_needs_refresh;
use super::validate_refresh_token_issuer;

pub(super) const REFRESH_REQUEST_TIMEOUT: Duration = Duration::from_secs(45);

impl OAuthPersistor {
    pub(crate) async fn refresh_if_needed(&self) -> Result<()> {
        self.refresh_if_needed_in(&DefaultKeyringStore, REFRESH_REQUEST_TIMEOUT)
            .await
    }

    /// Injects the credential backend and provider timeout for deterministic failure-path tests.
    pub(super) async fn refresh_if_needed_in<K: KeyringStore + Clone + 'static>(
        &self,
        keyring_store: &K,
        refresh_request_timeout: Duration,
    ) -> Result<()> {
        let expires_at = {
            let guard = self.inner.last_credentials.lock().await;
            guard.as_ref().and_then(|tokens| tokens.expires_at)
        };

        if !token_needs_refresh(expires_at) {
            return Ok(());
        }

        let persistor = self.clone();
        let keyring_store = keyring_store.clone();
        // Once the provider can consume a rotating token, caller cancellation must not cancel
        // persistence. The owned task continues with independently bounded lock and request waits.
        // A provider timeout leaves the outcome unknown and permits a later serialized retry:
        // provider grace may recover, otherwise reauthorization is unavoidable. This residual
        // risk is preferred to holding the credential lock indefinitely.
        let transaction_task = tokio::spawn(async move {
            let result = persistor
                .refresh_transaction(&keyring_store, refresh_request_timeout)
                .await;

            // Keep this summary inside the owned task so caller cancellation cannot suppress it.
            if let Err(error) = &result {
                warn!(
                    server_name = %persistor.inner.server_name,
                    refresh_reason = "expiry",
                    error = %error,
                    "MCP OAuth refresh transaction failed"
                );
            }

            result
        });
        transaction_task.await.with_context(|| {
            format!(
                "OAuth refresh task failed for server {}",
                self.inner.server_name
            )
        })?
    }

    #[expect(
        clippy::await_holding_invalid_type,
        reason = "AuthorizationManager async access must be serialized through its Tokio mutex"
    )]
    #[tracing::instrument(
        level = "debug",
        skip_all,
        fields(
            server_name = %self.inner.server_name,
            refresh_reason = "expiry",
        ),
        err
    )]
    async fn refresh_transaction<K: KeyringStore + Clone + 'static>(
        &self,
        keyring_store: &K,
        refresh_request_timeout: Duration,
    ) -> Result<()> {
        debug!("waiting for the MCP OAuth credential transaction lock");
        let _lock =
            RefreshCredentialLock::acquire_for_server(&self.inner.server_name, &self.inner.url)
                .await?;
        debug!("acquired the MCP OAuth credential transaction lock");

        // Stay on the lifecycle-pinned store. A failure is surfaced rather than falling back and
        // possibly replaying an older rotating refresh token from the other store.
        debug!("rereading authoritative MCP OAuth credentials");
        let latest = self.inner.credential_store.load(
            keyring_store,
            &self.inner.server_name,
            &self.inner.url,
        )?;

        // The pre-lock snapshot is only a hint. This locked reread is authoritative, so adopt a
        // winner from another process rather than refreshing its predecessor.
        let Some(latest) = latest else {
            let manager = self.inner.authorization_manager.clone();
            manager
                .lock()
                .await
                .set_credential_store(InMemoryCredentialStore::new());
            *self.inner.last_credentials.lock().await = None;
            return Err(AuthError::AuthorizationRequired).with_context(|| {
                format!(
                    "OAuth tokens for server {} were removed before refresh; authorization required",
                    self.inner.server_name
                )
            });
        };

        if !token_needs_refresh(latest.expires_at) {
            debug!("adopting newer MCP OAuth credentials without contacting the provider");
            let manager = self.inner.authorization_manager.clone();
            let mut guard = manager.lock().await;
            if latest.has_refresh_token() {
                let previous = self.inner.last_credentials.lock().await;
                let expected_issuer = previous.as_ref().and_then(StoredOAuthTokens::bound_issuer);
                let latest_issuer = latest.bound_issuer();
                if latest_issuer.is_none() || latest_issuer != expected_issuer {
                    return Err(AuthError::AuthorizationRequired).with_context(|| {
                        format!(
                            "OAuth refresh credentials for server {} could not be bound to the previously validated issuer; authorization required",
                            self.inner.server_name
                        )
                    });
                }
            }
            install_tokens_in_manager(&mut guard, &latest, self.inner.oauth_config.as_ref())
                .await?;
            *self.inner.last_credentials.lock().await = Some(latest);
            return Ok(());
        }

        // Without a refresh token, authorization is required before contacting the provider.
        if !latest.has_refresh_token() {
            return Err(AuthError::AuthorizationRequired).with_context(|| {
                format!(
                    "OAuth tokens for server {} cannot be refreshed; authorization required",
                    self.inner.server_name
                )
            });
        }

        let manager = self.inner.authorization_manager.clone();
        // The provider uses a separate HTTP client and cannot re-enter `AuthClient`. Retain this
        // async guard so requests cannot observe credentials while they are staged and committed.
        let mut guard = manager.lock().await;
        let metadata = guard
            .resolve_metadata()
            .await
            .context("failed to resolve OAuth metadata before using stored refresh credentials")?
            .metadata;
        validate_refresh_token_issuer(&metadata, &latest)?;
        guard.set_metadata(metadata);
        install_tokens_in_manager(&mut guard, &latest, self.inner.oauth_config.as_ref())
            .await
            .context("failed to stage OAuth credentials for refresh")?;
        // The owned task prevents caller deadlines from canceling after possible token rotation;
        // this timeout independently bounds the provider request.
        debug!(
            timeout_ms = refresh_request_timeout.as_millis(),
            "requesting refreshed MCP OAuth credentials from the provider"
        );
        let refreshed = match timeout(refresh_request_timeout, guard.refresh_token()).await {
            Ok(Ok(token_response)) => {
                debug!("received refreshed MCP OAuth credentials from the provider");
                refreshed_tokens(token_response, &latest, &self.inner)
            }
            Ok(Err(error @ AuthError::TokenRefreshRejected(_))) => {
                // Definitive rejection requires authorization even if the access token has not
                // expired yet. Other refresh failures below check actual access-token expiry.
                warn!(
                    error = %error,
                    "MCP OAuth refresh token was rejected; reauthorization required"
                );
                return Err(AuthError::AuthorizationRequired).with_context(|| {
                    format!(
                        "failed to refresh OAuth tokens for server {}: {error}",
                        self.inner.server_name
                    )
                });
            }
            Ok(Err(error)) => {
                warn!(
                    error = %error,
                    "MCP OAuth provider refresh failed"
                );
                let error = Error::new(error).context(format!(
                    "failed to refresh OAuth tokens for server {}",
                    self.inner.server_name
                ));
                return self
                    .recover_after_failed_refresh(keyring_store, &mut guard, &latest, error)
                    .await;
            }
            Err(_) => {
                warn!(
                    timeout_ms = refresh_request_timeout.as_millis(),
                    "MCP OAuth provider refresh timed out; the outcome is unknown and a later serialized retry is permitted"
                );
                let error = anyhow::anyhow!(
                    "timed out after {refresh_request_timeout:?} refreshing OAuth tokens for server {}",
                    self.inner.server_name
                );
                return self
                    .recover_after_failed_refresh(keyring_store, &mut guard, &latest, error)
                    .await;
            }
        };

        // Persist to the pinned source before exposing the refreshed token. On failure, restore
        // the prior in-process credential and return the error; serving an unpersisted token would
        // hide the root cause until a later process restart. If the provider already consumed the
        // prior token, the next refresh may require reauthorization. That is the deliberate
        // fail-closed policy.
        // TODO: Add a bounded persistence retry only if telemetry shows this is common; never
        // silently switch stores or continue with an unpersisted credential.
        debug!("persisting refreshed MCP OAuth credentials to the resolved store");
        let result = self.inner.credential_store.save_with_refresh_telemetry(
            keyring_store,
            &self.inner.server_name,
            &refreshed,
        );
        if let Err(error) = result {
            warn!(
                "failed to persist refreshed MCP OAuth credentials; returning the error and restoring the previous in-process credentials"
            );
            install_tokens_in_manager(&mut guard, &latest, self.inner.oauth_config.as_ref())
                .await
                .context(
                    "failed to restore previous OAuth credentials after refresh persistence failed",
                )?;
            return Err(error);
        }

        // This layer retains RMCP's legacy persistence hook. Install the same merged response
        // (including carried-forward refresh token/scopes) so that hook cannot overwrite durable
        // credentials with the provider's partial response.
        install_tokens_in_manager(&mut guard, &refreshed, self.inner.oauth_config.as_ref())
            .await
            .context(
                "refreshed OAuth tokens were persisted but could not be installed in the authorization manager",
            )?;
        *self.inner.last_credentials.lock().await = Some(refreshed);
        drop(guard);
        debug!("persisted refreshed MCP OAuth credentials and completed the transaction");
        Ok(())
    }

    async fn recover_after_failed_refresh<K: KeyringStore + Clone + 'static>(
        &self,
        keyring_store: &K,
        manager: &mut AuthorizationManager,
        previous: &StoredOAuthTokens,
        error: Error,
    ) -> Result<()> {
        // A failed proactive refresh does not require a new login while the access token is
        // still valid. Use actual expiry, not the 30-second refresh buffer.
        if !token_has_expired(previous.expires_at) {
            return Err(error);
        }

        // Browser login can finish while the provider request is pending. Reread the pinned
        // authority before prompting, and never delete or overwrite a replacement credential.
        let replacement = self.inner.credential_store.load(
            keyring_store,
            &self.inner.server_name,
            &self.inner.url,
        )?;
        if let Some(replacement) = replacement
            && !token_has_expired(replacement.expires_at)
            && !replacement.client_id.trim().is_empty()
            && !replacement
                .token_response
                .0
                .access_token()
                .secret()
                .trim()
                .is_empty()
        {
            // Match the existing pre-refresh adoption rule: refresh credentials must remain
            // bound to the issuer already validated for this authorization manager.
            if replacement.has_refresh_token()
                && (replacement.bound_issuer().is_none()
                    || replacement.bound_issuer() != previous.bound_issuer())
            {
                return Err(AuthError::AuthorizationRequired).context(
                    "replacement MCP OAuth refresh credentials do not match the validated issuer",
                );
            }
            debug!("adopting new MCP OAuth credentials after a failed refresh");
            install_tokens_in_manager(manager, &replacement, self.inner.oauth_config.as_ref())
                .await?;
            *self.inner.last_credentials.lock().await = Some(replacement);
            return Ok(());
        }

        warn!("MCP OAuth access token is expired and refresh failed; reauthorization required");
        // Keep AuthorizationRequired as the source so both startup classification and runtime
        // tool-call recovery recognize it; retain the original failure as diagnostic context.
        Err(Error::new(AuthError::AuthorizationRequired).context(error))
    }
}

fn token_has_expired(expires_at: Option<u64>) -> bool {
    expires_at.is_some_and(|expires_at| expires_in_from_timestamp(expires_at).is_none())
}

/// Installs tokens without resolving metadata again, so callers can pin the validated snapshot.
pub(crate) async fn install_tokens_in_manager(
    authorization_manager: &mut AuthorizationManager,
    tokens: &StoredOAuthTokens,
    oauth_config: Option<&McpServerOAuthConfig>,
) -> Result<()> {
    let credentials = OAuthClientCredentials::resolve(oauth_config)?;
    credentials.validate_stored_client_id(&tokens.client_id)?;
    let store = InMemoryCredentialStore::new();
    let token_response = tokens.token_response.0.clone();
    let granted_scopes = token_response
        .scopes()
        .map(|scopes| scopes.iter().map(|scope| scope.to_string()).collect())
        .unwrap_or_default();
    let token_received_at = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_secs());
    store
        .save(
            StoredCredentials::new(
                tokens.client_id.clone(),
                Some(token_response),
                granted_scopes,
                token_received_at,
            )
            .with_issuer(tokens.issuer.clone()),
        )
        .await
        .context("failed to stage OAuth tokens for authorization manager")?;

    authorization_manager.set_credential_store(store);
    // TODO(stevenlee): Add an RMCP adoption API that atomically updates credentials, client ID,
    // and private `current_scopes`; this path cannot synchronize RMCP's scope-upgrade state.
    authorization_manager
        .initialize_from_store()
        .await
        .context("failed to adopt refreshed OAuth tokens")?;
    credentials.configure_for_refresh(authorization_manager, &tokens.url, &tokens.client_id)?;
    Ok(())
}

fn refreshed_tokens(
    mut token_response: OAuthTokenResponse,
    previous: &StoredOAuthTokens,
    inner: &OAuthPersistorInner,
) -> StoredOAuthTokens {
    if token_response.refresh_token().is_none() {
        token_response.set_refresh_token(previous.token_response.0.refresh_token().cloned());
    }
    if token_response.scopes().is_none() {
        token_response.set_scopes(previous.token_response.0.scopes().cloned());
    }
    StoredOAuthTokens {
        server_name: inner.server_name.clone(),
        url: inner.url.clone(),
        issuer: previous.issuer.clone(),
        client_id: previous.client_id.clone(),
        expires_at: compute_expires_at_millis(&token_response),
        token_response: WrappedOAuthTokenResponse(token_response),
    }
}

//! Auth elicitation helpers.
//!
//! This module owns protocol-neutral auth elicitation parsing and payload shaping.
//! Session orchestration stays in `codex-core`.

use codex_protocol::mcp::CallToolResult;
use serde::Serialize;

pub const MCP_TOOL_CODEX_APPS_META_KEY: &str = "_codex_apps";
pub const CONNECTOR_AUTH_FAILURE_META_KEY: &str = "connector_auth_failure";
pub const CONNECTOR_AUTH_FAILURE_IS_AUTH_FAILURE_KEY: &str = "is_auth_failure";
pub const CONNECTOR_AUTH_FAILURE_AUTH_REASON_KEY: &str = "auth_reason";
pub const CONNECTOR_AUTH_FAILURE_CONNECTOR_ID_KEY: &str = "connector_id";
pub const CONNECTOR_AUTH_FAILURE_LINK_ID_KEY: &str = "link_id";
pub const CONNECTOR_AUTH_FAILURE_ERROR_CODE_KEY: &str = "error_code";
pub const CONNECTOR_AUTH_FAILURE_ERROR_HTTP_STATUS_CODE_KEY: &str = "error_http_status_code";
pub const CONNECTOR_AUTH_FAILURE_ERROR_ACTION_KEY: &str = "error_action";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CodexAppsConnectorAuthFailure {
    pub connector_id: String,
    pub connector_name: String,
    pub install_url: String,
    pub auth_reason: Option<String>,
    pub link_id: Option<String>,
    pub error_code: Option<String>,
    pub error_http_status_code: Option<i64>,
    pub error_action: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CodexAppsAuthElicitation {
    pub meta: serde_json::Value,
    pub message: String,
    pub url: String,
    pub elicitation_id: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CodexAppsAuthElicitationPlan {
    pub auth_failure: CodexAppsConnectorAuthFailure,
    pub elicitation: CodexAppsAuthElicitation,
}

#[derive(Serialize)]
struct CodexAppsConnectorAuthFailureMeta<'a> {
    is_auth_failure: bool,
    connector_id: &'a str,
    connector_name: &'a str,
    install_url: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    auth_reason: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    link_id: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error_code: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error_http_status_code: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error_action: Option<&'a str>,
}

pub fn connector_auth_failure_from_tool_result(
    result: &CallToolResult,
    connector_id: Option<&str>,
    connector_name: Option<&str>,
    install_url: Option<String>,
) -> Option<CodexAppsConnectorAuthFailure> {
    let connector_id = connector_id
        .map(str::trim)
        .filter(|connector_id| !connector_id.is_empty())?;
    let auth_failure = connector_auth_failure_metadata(result, connector_id)?;
    let connector_name = connector_name
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .unwrap_or(connector_id)
        .to_string();

    Some(CodexAppsConnectorAuthFailure {
        connector_id: connector_id.to_string(),
        connector_name,
        install_url: install_url?,
        auth_reason: string_auth_failure_field(
            auth_failure,
            CONNECTOR_AUTH_FAILURE_AUTH_REASON_KEY,
        ),
        link_id: string_auth_failure_field(auth_failure, CONNECTOR_AUTH_FAILURE_LINK_ID_KEY),
        error_code: string_auth_failure_field(auth_failure, CONNECTOR_AUTH_FAILURE_ERROR_CODE_KEY),
        error_http_status_code: auth_failure
            .get(CONNECTOR_AUTH_FAILURE_ERROR_HTTP_STATUS_CODE_KEY)
            .and_then(serde_json::Value::as_i64),
        error_action: string_auth_failure_field(
            auth_failure,
            CONNECTOR_AUTH_FAILURE_ERROR_ACTION_KEY,
        ),
    })
}

pub fn is_connector_auth_failure_from_tool_result(
    result: &CallToolResult,
    connector_id: Option<&str>,
) -> bool {
    connector_id
        .map(str::trim)
        .filter(|connector_id| !connector_id.is_empty())
        .is_some_and(|connector_id| connector_auth_failure_metadata(result, connector_id).is_some())
}

fn connector_auth_failure_metadata<'a>(
    result: &'a CallToolResult,
    connector_id: &str,
) -> Option<&'a serde_json::Map<String, serde_json::Value>> {
    if result.is_error != Some(true) {
        return None;
    }

    let auth_failure = result
        .meta
        .as_ref()?
        .as_object()?
        .get(MCP_TOOL_CODEX_APPS_META_KEY)?
        .as_object()?
        .get(CONNECTOR_AUTH_FAILURE_META_KEY)?
        .as_object()?;
    if auth_failure
        .get(CONNECTOR_AUTH_FAILURE_IS_AUTH_FAILURE_KEY)
        .and_then(serde_json::Value::as_bool)
        != Some(true)
    {
        return None;
    }
    if let Some(auth_failure_connector_id) =
        string_auth_failure_field(auth_failure, CONNECTOR_AUTH_FAILURE_CONNECTOR_ID_KEY)
        && auth_failure_connector_id != connector_id
    {
        return None;
    }

    Some(auth_failure)
}

pub fn build_auth_elicitation_plan(
    call_id: &str,
    result: &CallToolResult,
    connector_id: Option<&str>,
    connector_name: Option<&str>,
    install_url: Option<String>,
) -> Option<CodexAppsAuthElicitationPlan> {
    let auth_failure =
        connector_auth_failure_from_tool_result(result, connector_id, connector_name, install_url)?;
    let elicitation = build_auth_elicitation(call_id, &auth_failure);
    Some(CodexAppsAuthElicitationPlan {
        auth_failure,
        elicitation,
    })
}

pub fn build_auth_elicitation(
    call_id: &str,
    auth_failure: &CodexAppsConnectorAuthFailure,
) -> CodexAppsAuthElicitation {
    CodexAppsAuthElicitation {
        meta: serde_json::json!({
            MCP_TOOL_CODEX_APPS_META_KEY: {
                CONNECTOR_AUTH_FAILURE_META_KEY: CodexAppsConnectorAuthFailureMeta {
                    is_auth_failure: true,
                    connector_id: &auth_failure.connector_id,
                    connector_name: &auth_failure.connector_name,
                    install_url: &auth_failure.install_url,
                    auth_reason: auth_failure.auth_reason.as_deref(),
                    link_id: auth_failure.link_id.as_deref(),
                    error_code: auth_failure.error_code.as_deref(),
                    error_http_status_code: auth_failure.error_http_status_code,
                    error_action: auth_failure.error_action.as_deref(),
                },
            },
        }),
        message: auth_elicitation_message(auth_failure),
        url: auth_failure.install_url.clone(),
        elicitation_id: auth_elicitation_id(call_id),
    }
}

pub fn auth_elicitation_completed_result(
    auth_failure: &CodexAppsConnectorAuthFailure,
    meta: Option<serde_json::Value>,
) -> CallToolResult {
    CallToolResult {
        content: vec![serde_json::json!({
            "type": "text",
            "text": format!(
                "Authentication for {} was requested and accepted. Retry this tool call now.",
                auth_failure.connector_name
            ),
        })],
        structured_content: None,
        is_error: Some(true),
        meta,
    }
}

pub fn auth_elicitation_id(call_id: &str) -> String {
    format!("codex_apps_auth_{call_id}")
}

fn string_auth_failure_field(
    auth_failure: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<String> {
    auth_failure
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
}

fn auth_elicitation_message(auth_failure: &CodexAppsConnectorAuthFailure) -> String {
    match auth_failure.auth_reason.as_deref() {
        Some("oauth_upgrade_required") => format!(
            "Reconnect {} on ChatGPT to grant the permissions needed for this request.",
            auth_failure.connector_name
        ),
        Some("reauthentication_required") => format!(
            "Reconnect {} on ChatGPT to restore access for this request.",
            auth_failure.connector_name
        ),
        Some("missing_link") => format!(
            "Sign in to {} on ChatGPT to use it in Codex.",
            auth_failure.connector_name
        ),
        _ => format!(
            "Sign in to {} on ChatGPT to continue.",
            auth_failure.connector_name
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use pretty_assertions::assert_eq;

    fn auth_failure_result() -> CallToolResult {
        CallToolResult {
            content: vec![serde_json::json!({
                "type": "text",
                "text": "Connector reauthentication required",
            })],
            structured_content: None,
            is_error: Some(true),
            meta: Some(serde_json::json!({
                MCP_TOOL_CODEX_APPS_META_KEY: {
                    CONNECTOR_AUTH_FAILURE_META_KEY: {
                        CONNECTOR_AUTH_FAILURE_IS_AUTH_FAILURE_KEY: true,
                        CONNECTOR_AUTH_FAILURE_AUTH_REASON_KEY: "reauthentication_required",
                        CONNECTOR_AUTH_FAILURE_CONNECTOR_ID_KEY: "connector_calendar",
                        "connector_name": "Untrusted Calendar",
                        CONNECTOR_AUTH_FAILURE_LINK_ID_KEY: "link_123",
                        CONNECTOR_AUTH_FAILURE_ERROR_CODE_KEY: "UNAUTHORIZED",
                        CONNECTOR_AUTH_FAILURE_ERROR_HTTP_STATUS_CODE_KEY: 401,
                        CONNECTOR_AUTH_FAILURE_ERROR_ACTION_KEY: "TRIGGER_REAUTHENTICATION",
                    },
                },
            })),
        }
    }

    #[test]
    fn parses_auth_failure_from_trusted_connector_metadata() {
        assert_eq!(
            connector_auth_failure_from_tool_result(
                &auth_failure_result(),
                Some("connector_calendar"),
                Some("Google Calendar"),
                Some("https://chatgpt.com/apps/google-calendar/connector_calendar".to_string()),
            ),
            Some(CodexAppsConnectorAuthFailure {
                connector_id: "connector_calendar".to_string(),
                connector_name: "Google Calendar".to_string(),
                install_url: "https://chatgpt.com/apps/google-calendar/connector_calendar"
                    .to_string(),
                auth_reason: Some("reauthentication_required".to_string()),
                link_id: Some("link_123".to_string()),
                error_code: Some("UNAUTHORIZED".to_string()),
                error_http_status_code: Some(401),
                error_action: Some("TRIGGER_REAUTHENTICATION".to_string()),
            })
        );
    }

    #[test]
    fn rejects_missing_or_mismatched_connector_ids() {
        assert_eq!(
            connector_auth_failure_from_tool_result(
                &auth_failure_result(),
                /*connector_id*/ None,
                Some("Google Calendar"),
                Some("https://chatgpt.com/apps/google-calendar/connector_calendar".to_string()),
            ),
            None
        );
        assert_eq!(
            connector_auth_failure_from_tool_result(
                &auth_failure_result(),
                Some("connector_drive"),
                Some("Google Drive"),
                Some("https://chatgpt.com/apps/google-drive/connector_drive".to_string()),
            ),
            None
        );
    }

    #[test]
    fn detects_auth_failure_without_an_install_url() {
        let result = auth_failure_result();

        assert_eq!(
            is_connector_auth_failure_from_tool_result(&result, Some("connector_calendar")),
            true
        );
        assert_eq!(
            connector_auth_failure_from_tool_result(
                &result,
                Some("connector_calendar"),
                Some("Google Calendar"),
                /*install_url*/ None,
            ),
            None
        );
    }

    #[test]
    fn auth_failure_detection_requires_trusted_connector_identity_and_auth_flag() {
        let result = auth_failure_result();
        assert_eq!(
            is_connector_auth_failure_from_tool_result(&result, /*connector_id*/ None),
            false
        );
        assert_eq!(
            is_connector_auth_failure_from_tool_result(&result, Some("connector_drive")),
            false
        );

        let mut ordinary_error = result.clone();
        ordinary_error.meta.as_mut().expect("auth metadata")[MCP_TOOL_CODEX_APPS_META_KEY]
            [CONNECTOR_AUTH_FAILURE_META_KEY][CONNECTOR_AUTH_FAILURE_IS_AUTH_FAILURE_KEY] =
            serde_json::Value::Bool(false);
        assert_eq!(
            is_connector_auth_failure_from_tool_result(&ordinary_error, Some("connector_calendar"),),
            false
        );

        let mut successful_result = result;
        successful_result.is_error = Some(false);
        assert_eq!(
            is_connector_auth_failure_from_tool_result(
                &successful_result,
                Some("connector_calendar"),
            ),
            false
        );
    }

    #[test]
    fn detects_each_supported_connector_auth_reason() {
        for auth_reason in [
            "missing_link",
            "oauth_upgrade_required",
            "reauthentication_required",
        ] {
            let mut result = auth_failure_result();
            result.meta.as_mut().expect("auth metadata")[MCP_TOOL_CODEX_APPS_META_KEY]
                [CONNECTOR_AUTH_FAILURE_META_KEY][CONNECTOR_AUTH_FAILURE_AUTH_REASON_KEY] =
                serde_json::Value::String(auth_reason.to_string());

            assert_eq!(
                is_connector_auth_failure_from_tool_result(&result, Some("connector_calendar")),
                true
            );
        }
    }

    #[test]
    fn builds_url_elicitation_payload() {
        let auth_failure = connector_auth_failure_from_tool_result(
            &auth_failure_result(),
            Some("connector_calendar"),
            Some("Google Calendar"),
            Some("https://chatgpt.com/apps/google-calendar/connector_calendar".to_string()),
        )
        .expect("auth failure");

        assert_eq!(
            build_auth_elicitation("call_123", &auth_failure),
            CodexAppsAuthElicitation {
                meta: serde_json::json!({
                    MCP_TOOL_CODEX_APPS_META_KEY: {
                        CONNECTOR_AUTH_FAILURE_META_KEY: {
                            CONNECTOR_AUTH_FAILURE_IS_AUTH_FAILURE_KEY: true,
                            CONNECTOR_AUTH_FAILURE_CONNECTOR_ID_KEY: "connector_calendar",
                            "connector_name": "Google Calendar",
                            "install_url":
                                "https://chatgpt.com/apps/google-calendar/connector_calendar",
                            CONNECTOR_AUTH_FAILURE_AUTH_REASON_KEY: "reauthentication_required",
                            CONNECTOR_AUTH_FAILURE_LINK_ID_KEY: "link_123",
                            CONNECTOR_AUTH_FAILURE_ERROR_CODE_KEY: "UNAUTHORIZED",
                            CONNECTOR_AUTH_FAILURE_ERROR_HTTP_STATUS_CODE_KEY: 401,
                            CONNECTOR_AUTH_FAILURE_ERROR_ACTION_KEY: "TRIGGER_REAUTHENTICATION",
                        },
                    },
                }),
                message: "Reconnect Google Calendar on ChatGPT to restore access for this request."
                    .to_string(),
                url: "https://chatgpt.com/apps/google-calendar/connector_calendar".to_string(),
                elicitation_id: "codex_apps_auth_call_123".to_string(),
            }
        );
    }

    #[test]
    fn builds_auth_elicitation_plan() {
        let plan = build_auth_elicitation_plan(
            "call_123",
            &auth_failure_result(),
            Some("connector_calendar"),
            Some("Google Calendar"),
            Some("https://chatgpt.com/apps/google-calendar/connector_calendar".to_string()),
        )
        .expect("auth elicitation plan");

        assert_eq!(plan.auth_failure.connector_name, "Google Calendar");
        assert_eq!(plan.elicitation.elicitation_id, "codex_apps_auth_call_123");
    }
}

