//! Registration wire compatibility for each supported actor entry point.

use super::*;
use pretty_assertions::assert_eq;
use serde_json::json;

#[test]
fn registration_serializes_the_supported_actor_authorizations() {
    let installation_id = "00000000-0000-4000-8000-000000000001";
    for (authorization, expected) in [
        (
            AuthenticatedActorAuthorization::Oauth {
                credential: "secret".into(),
            },
            json!({"type": "oauth", "credential": "secret"}),
        ),
        (
            AuthenticatedActorAuthorization:[REDACTED] {
                credential: "secret".into(),
            },
            json!({"type": "personal_access_token", "credential": "secret"}),
        ),
        (
            AuthenticatedActorAuthorization:[REDACTED] {
                credential: "secret".into(),
            },
            json!({"type": "platform_api_key", "credential": "secret"}),
        ),
    ] {
        let request = RuntimeRegistrationRequest {
            actor_auth: authorization,
            agent_host_auth: AgentHostAuthorization:[REDACTED] {
                installation_id: installation_id.parse().unwrap(),
            },
            public_key: "ssh-ed25519 public-key".into(),
            metadata: RuntimeRegistrationMetadata {
                harness: Some("codex".into()),
                harness_version: Some("0.0.0".into()),
                role: RuntimeRole::OrchestratorAndExecutor,
            },
        };
        assert!(!format!("{request:?}").contains("secret"));
        assert_eq!(
            serde_json::to_value(request).unwrap(),
            json!({
                "actor_auth": expected,
                "agent_host_auth": {"type": "installation_id", "installation_id": installation_id},
                "public_key": "ssh-ed25519 public-key",
                "metadata": {"harness": "codex", "harness_version": "0.0.0", "role": "orchestrator_and_executor"},
            })
        );
    }
}

#[test]
fn registration_decodes_composite_actor_contexts() {
    for (actor, expected) in [
        (
            json!({"kind": "chatgpt", "user_id": "user", "account_id": "account"}),
            ActorInfo::Chatgpt {
                user_id: "user".into(),
                account_id: "account".into(),
            },
        ),
        (
            json!({"kind": "platform", "user_id": "user", "organization_id": "org", "project_id": "project"}),
            ActorInfo::Platform {
                user_id: "user".into(),
                organization_id: "org".into(),
                project_id: Some("project".into()),
            },
        ),
    ] {
        let response: RuntimeRegistrationResponse = serde_json::from_value(json!({
            "runtime_agent_instance_id": "runtime", "agent_host_id": "host", "actor": actor,
        }))
        .unwrap();
        assert_eq!(
            response,
            RuntimeRegistrationResponse {
                runtime_agent_instance_id: "runtime".into(),
                agent_host_id: "host".into(),
                actor: expected,
            }
        );
    }
    assert!(
        serde_json::from_value::<RuntimeRegistrationResponse>(
            json!({"runtime_agent_instance_id": "runtime"})
        )
        .is_err()
    );
    assert!(
        serde_json::from_value::<ActorInfo>(json!({"kind": "platform", "user_id": "user"}))
            .is_err()
    );
}

//! Fresh draft entry and composer-local Vim search remain separate input paths.

use super::super::InputResult;
use super::super::tests::snapshot_composer_state_with_width;
use super::super::tests::type_chars_humanlike;
use crate::keymap::KeyChordMatch;
use crate::keymap::KeyChordMatcher;
use crate::keymap::RuntimeKeymap;
use codex_config::types::TuiKeymap;
use crossterm::event::KeyCode;
use crossterm::event::KeyEvent;
use crossterm::event::KeyModifiers;
use pretty_assertions::assert_eq;

#[test]
fn fresh_vim_draft_records_typing_after_submission() {
    snapshot_composer_state_with_width(
        "vim_fresh_draft",
        /*width*/ 40,
        /*enhanced_keys_supported*/ false,
        |composer| {
            composer.set_disable_paste_burst(/*disabled*/ true);
            for entry in [KeyCode::Char('i'), KeyCode::Esc] {
                composer.set_text_content("sent".into(), Vec::new(), Vec::new());
                composer.set_vim_enabled(/*enabled*/ true);
                composer.handle_key_event(entry.into());
                let (result, _) = composer.handle_key_event(KeyCode::Enter.into());
                assert!(matches!(result, InputResult::Submitted { .. }));
                assert_eq!(composer.draft.textarea.vim_mode_label(), Some("Insert"));
                for key in [KeyCode::Char('x'), KeyCode::Esc, KeyCode::Char('.')] {
                    composer.handle_key_event(key.into());
                }
                assert_eq!(composer.current_text(), "xx");
            }
            composer.handle_key_event(KeyCode::Enter.into());
        },
    );
}

#[test]
fn backspace_cancels_empty_vim_search() {
    snapshot_composer_state_with_width(
        "vim_search_cancelled",
        /*width*/ 40,
        /*enhanced_keys_supported*/ false,
        |composer| {
            for text in ["", "draft"] {
                composer.set_text_content(text.into(), Vec::new(), Vec::new());
                composer.set_vim_enabled(/*enabled*/ true);
                let cursor = composer.cursor();
                for prefix in ["/", "?", "d/", "d?", "c/", "c?", "y/", "y?"] {
                    if text.is_empty() && prefix == "/" {
                        continue;
                    }
                    for ch in prefix.chars() {
                        composer
                            .handle_key_event(KeyEvent::new(KeyCode::Char(ch), KeyModifiers::NONE));
                    }
                    assert!(composer.draft.textarea.vim_query().is_some());
                    composer.handle_key_event(KeyCode::Backspace.into());
                    assert!(!composer.draft.textarea.is_vim_operator_pending());
                    assert!(composer.draft.textarea.is_vim_normal_mode());
                    assert_eq!(
                        (composer.current_text(), composer.cursor()),
                        (text.into(), cursor)
                    );
                }
            }
        },
    );
}

