#[test]
fn search_batch_read_failure_stops_after_bounded_retries() {
    let (mut history, tx, mut rx) = history(/*entry_count*/ 5);
    let cursor = start_older_search(
        &mut history,
        &tx,
        &mut rx,
        "retry",
        /*newest_offset*/ 4,
    );

    for _ in 0..MAX_BATCH_READ_RETRIES {
        assert_eq!(
            history.on_batch_error(/*log_id*/ 42, cursor, &tx),
            Some(HistorySearchResult::Pending)
        );
        let (retry_cursor, log_id) = recv_batch_request(&mut rx);
        assert_eq!((retry_cursor, log_id), (cursor, 42));
    }

    assert_eq!(
        history.on_batch_error(/*log_id*/ 42, cursor, &tx),
        Some(HistorySearchResult::Unavailable)
    );
    assert!(rx.try_recv().is_err());
    assert!(history.search.is_none());
    assert_eq!(
        history.search(
            "retry",
            HistorySearchDirection::Older,
            /*restart*/ false,
            &tx,
        ),
        HistorySearchResult::Pending
    );
    assert_eq!(recv_entry_request(&mut rx), (3, 42));
}

#[test]
fn search_batch_match_preserves_cursor_for_next_older_search() {
    let (mut history, tx, mut rx) = history(/*entry_count*/ 7);
    let cursor = start_older_search(
        &mut history,
        &tx,
        &mut rx,
        "needle",
        /*newest_offset*/ 6,
    );
    let continuation = HistoryBatchCursor::new(/*end_offset*/ 2);

    assert_eq!(
        history.on_batch_response(
            /*log_id*/ 42,
            cursor,
            vec![
                batch_entry(/*offset*/ 5, "unrelated newer"),
                batch_entry(/*offset*/ 4, "needle first"),
                batch_entry(/*offset*/ 3, "unrelated older"),
            ],
            Some(continuation),
            &tx,
        ),
        Some(found("needle first"))
    );

    assert_eq!(
        history.search(
            "needle",
            HistorySearchDirection::Older,
            /*restart*/ false,
            &tx,
        ),
        HistorySearchResult::Pending
    );
    let (requested_cursor, _) = recv_batch_request(&mut rx);
    assert_eq!(requested_cursor, continuation);
    assert!(rx.try_recv().is_err());

    assert_eq!(
        history.on_batch_response(
            /*log_id*/ 42,
            continuation,
            vec![batch_entry(/*offset*/ 2, "needle second")],
            /*next_older_cursor*/ None,
            &tx,
        ),
        Some(found("needle second"))
    );
}

#[test]
fn search_batch_absent_1024_uses_one_single_and_eight_batches() {
    let (mut history, tx, mut rx) = history(/*entry_count*/ 1_024);
    let mut cursor = start_older_search(
        &mut history,
        &tx,
        &mut rx,
        "absent",
        /*newest_offset*/ 1_023,
    );
    let mut batches = 0;

    loop {
        let end_offset = cursor.end_offset();
        let start_offset = end_offset.saturating_sub(127);
        let entries = (start_offset..=end_offset)
            .rev()
            .map(|offset| batch_entry(offset, "unrelated entry"))
            .collect();
        let next_older_cursor = start_offset.checked_sub(1).map(HistoryBatchCursor::new);
        let expected = if next_older_cursor.is_some() {
            HistorySearchResult::Pending
        } else {
            HistorySearchResult::NotFound
        };
        assert_eq!(
            history.on_batch_response(/*log_id*/ 42, cursor, entries, next_older_cursor, &tx,),
            Some(expected)
        );
        batches += 1;
        let Some(expected_cursor) = next_older_cursor else {
            break;
        };
        let (next, _) = recv_batch_request(&mut rx);
        assert_eq!(next, expected_cursor);
        cursor = next;
    }

    assert_eq!((1 + batches, batches), (9, 8));
    assert!(rx.try_recv().is_err());
}

//! Pasted text edits the active history query while preserving the original draft.

use super::super::super::chat_composer_history::HistoryEntry;
use super::super::super::chat_composer_history::HistorySearchResult;
use super::super::ChatComposer;
use super::super::ComposerRenderOptions;
use super::super::InputResult;
use super::super::LARGE_PASTE_CHAR_THRESHOLD;
use crate::app_event_sender::AppEventSender;
use crate::render::renderable::Renderable;
use crossterm::event::KeyCode;
use crossterm::event::KeyEvent;
use crossterm::event::KeyModifiers;
use pretty_assertions::assert_eq;
use ratatui::Terminal;
use ratatui::backend::TestBackend;
use tokio::sync::mpsc::unbounded_channel;

fn composer_with_history() -> ChatComposer {
    let (tx, _rx) = unbounded_channel();
    let mut composer = ChatComposer::new(
        /*has_input_focus*/ true,
        AppEventSender::new(tx),
        /*enhanced_keys_supported*/ false,
        "Ask Codex to do anything".to_string(),
        /*disable_paste_burst*/ false,
    );
    for entry in ["git status", "git log"] {
        composer
            .history
            .record_local_submission(HistoryEntry::new(entry.to_string()));
    }
    composer.set_text_content("draft".to_string(), Vec::new(), Vec::new());
    composer
}

fn render_composer(composer: &ChatComposer, width: u16) -> Terminal<TestBackend> {
    let mut terminal = Terminal::new(TestBackend::new(width, /*height*/ 5)).unwrap();
    terminal
        .draw(|frame| composer.render(frame.area(), frame.buffer_mut()))
        .unwrap();
    terminal
}

#[test]
fn history_search_paste_appends_query_and_accepts_match() {
    let mut composer = composer_with_history();
    composer.handle_key_event(KeyEvent::new(KeyCode::Char('r'), KeyModifiers::CONTROL));
    assert!(composer.handle_paste("git".to_string()));
    assert_eq!(composer.draft.textarea.text(), "git log");

    composer.handle_key_event(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE));
    let paste_target = composer.clipboard_paste_target(Some(KeyCode::Insert));
    // A background history lookup changes the preview, not the query being edited.
    composer.apply_history_search_result(HistorySearchResult::Found(HistoryEntry::new(
        "git diff".into(),
    )));
    assert_eq!(
        composer.clipboard_paste_target(Some(KeyCode::Insert)),
        paste_target
    );
    assert!(composer.handle_paste("status".to_string()));
    assert_ne!(
        composer.clipboard_paste_target(Some(KeyCode::Insert)),
        paste_target
    );
    assert_eq!(
        composer.history_search.as_ref().unwrap().query,
        "git status"
    );
    assert_eq!(composer.draft.textarea.text(), "git status");

    let terminal = render_composer(&composer, /*width*/ 70);
    insta::assert_snapshot!("history_search_pasted_query", terminal.backend());

    let (result, _) = composer.handle_key_event(KeyCode::Enter.into());
    assert!(matches!(result, InputResult::None));
    assert!(!composer.history_search_active());
    assert_eq!(composer.draft.textarea.text(), "git status");
}

